from itertools import product

# Build the base hook: 3x3 grid, cells (x,y) with x,y in {0,1,2}
# Base hook cells (from analysis):
# Row2: ###  -> (0,2),(1,2),(2,2)
# Row1: #.#  -> (0,1),(2,1)
# Row0: ..#  -> (2,0)
base = {(0,1),(0,2),(1,2),(2,0),(2,1),(2,2)}

# Generate all 8 orientations (rotations + reflections) = dihedral group
def transform(cells, f):
    return {f(x,y) for (x,y) in cells}

transforms = [
    lambda x,y:(x,y),
    lambda x,y:(2-x,y),
    lambda x,y:(x,2-y),
    lambda x,y:(2-x,2-y),
    lambda x,y:(y,2-x),
    lambda x,y:(2-y,2-x),
    lambda x,y:(y,x),
    lambda x,y:(2-y,x),
]
orientations = []
seen = set()
for t in transforms:
    s = frozenset(transform(base,t))
    if s not in seen:
        seen.add(s)
        orientations.append(s)
print("Num distinct orientations:", len(orientations))
for o in orientations:
    print(sorted(o))

# Generate all placements in an m x n grid
def placements(m, n):
    result = []
    for o in orientations:
        # bounding box is 3x3, place at (dx, dy) where dx in 0..n-3, dy in 0..m-3
        for dx in range(n-2):
            for dy in range(m-2):
                cells = frozenset((x+dx, y+dy) for (x,y) in o)
                result.append(cells)
    return result

# Exact cover via backtracking
def can_tile(m, n):
    if m < 3 or n < 3:
        return False
    if (m*n) % 6 != 0:
        return False
    all_cells = frozenset((x,y) for x in range(n) for y in range(m))
    pls = placements(m, n)
    # dedupe
    pls = list(set(pls))
    # backtracking with cell ordering
    cells_list = sorted(all_cells)
    cell_index = {c:i for i,c in enumerate(cells_list)}
    # for each cell, which placements cover it
    cell_to_placements = {c: [] for c in all_cells}
    for p in pls:
        for c in p:
            cell_to_placements[c].append(p)

    used = [False]*len(pls)
    covered = set()

    def backtrack():
        if len(covered) == m*n:
            return True
        # pick uncovered cell with fewest options (MRV)
        uncovered = [c for c in all_cells if c not in covered]
        if not uncovered:
            return len(covered)==m*n
        # choose cell with min options
        best_cell = None
        best_opts = None
        for c in uncovered:
            opts = [p for p in cell_to_placements[c] if not used[pls.index(p)] and p.isdisjoint(covered)]
            if best_opts is None or len(opts) < len(best_opts):
                best_cell = c
                best_opts = opts
                if len(opts)==0:
                    return False
                if len(opts)==1:
                    break
        for p in best_opts:
            idx = pls.index(p)
            if used[idx]: continue
            if not p.isdisjoint(covered): continue
            used[idx]=True
            covered.update(p)
            if backtrack():
                return True
            covered.difference_update(p)
            used[idx]=False
        return False

    return backtrack()

# Check small cases
